import numpy as np
inp={(0,0),(0,1),(1,1),(1,2),(2,0),(2,1)}
out={(0,0),(0,2),(1,0),(1,1),(1,2),(2,1)}
def transforms(S):
 a=np.zeros((3,3),int)
 for r,c in S:a[r,c]=1
 for k in range(4):
  b=np.rot90(a,k)
  yield k,'rot', {(r,c) for r in range(3) for c in range(3) if b[r,c]}
  yield k,'flip', {(r,c) for r in range(3) for c in range(3) if np.fliplr(b)[r,c]}
[(k,t) for k,t,s in transforms(inp) if s==out]
